-- Hosbah queries. Written by the deploy worker (system scope); read by the team.
-- name: InsertRelease :one
INSERT INTO releases (id, team_id, app_id, deployment_id, version, image, commit_sha, port, host_port, containers, config, status, activated_at)
VALUES (sqlc.arg('id'), sqlc.arg('team_id'), sqlc.arg('app_id'), sqlc.arg('deployment_id'),
    (SELECT coalesce(max(r.version), 0) + 1 FROM releases r WHERE r.app_id = sqlc.arg('app_id')),
    sqlc.arg('image'), sqlc.narg('commit_sha'), sqlc.arg('port'), sqlc.narg('host_port'), sqlc.narg('containers'),
    sqlc.arg('config'), 'live', now())
RETURNING *;

-- name: RetireLiveRelease :exec
UPDATE releases SET status = 'standby', updated_at = now() WHERE app_id = $1 AND status = 'live';

-- name: ActivateRelease :exec
-- A rollback: a kept release takes traffic again, in new containers.
UPDATE releases SET status = 'live', host_port = sqlc.narg('host_port'), containers = sqlc.narg('containers'),
    activated_at = now(), updated_at = now()
WHERE id = sqlc.arg('id') AND status = 'standby';

-- name: ListReleasesOfApp :many
SELECT * FROM releases WHERE app_id = $1 AND team_id = $2 ORDER BY version DESC LIMIT $3;

-- name: ReleaseInTeam :one
