-- name: PreviousReleaseOfApp :one
-- The release that was live most recently before the current one.
SELECT * FROM releases WHERE app_id = $1 AND status = 'standby' ORDER BY activated_at DESC NULLS LAST, version DESC LIMIT 1;

-- name: MarkReleasesPruned :exec
UPDATE releases SET status = 'pruned', updated_at = now()
WHERE app_id = sqlc.arg('app_id') AND status = 'standby' AND image = ANY(string_to_array(sqlc.arg('images')::text, ','));

-- name: SetReleaseContainers :exec
-- A restart: the live release, in new containers.
UPDATE releases SET host_port = sqlc.narg('host_port'), containers = sqlc.narg('containers'), updated_at = now()
WHERE id = sqlc.arg('id');
